package io.lumine.mythic.lib.api.util.ui;
import java.text.MessageFormat;import java.util.*;
public class FriendlyFeedbackProvider {
 private final FriendlyFeedbackPalette palette; private final EnumMap<FriendlyFeedbackCategory,ArrayList<FriendlyFeedbackMessage>> feedback=new EnumMap<>(FriendlyFeedbackCategory.class); private FriendlyFeedbackMessage prefixSample=new FriendlyFeedbackMessage("",false);
 public FriendlyFeedbackProvider(){this(null);} public FriendlyFeedbackProvider(FriendlyFeedbackPalette palette){this.palette=palette;} public FriendlyFeedbackPalette getPalette(){return palette;} public ArrayList<FriendlyFeedbackMessage> getFeedbackOf(FriendlyFeedbackCategory c){return feedback.computeIfAbsent(c,k->new ArrayList<>());} public List<String> getFeedback(){ArrayList<String> out=new ArrayList<>();for(var list:feedback.values())for(var m:list)out.add(m.getMessage());return List.copyOf(out);} public boolean isEmpty(){return messagesTotal()==0;} public void clearFeedbackOf(FriendlyFeedbackCategory c){feedback.remove(c);} public void clearFeedback(){feedback.clear();}
 public void log(String s){log(FriendlyFeedbackCategory.INFORMATION,s);} public void provide(String s){log(s);} public void log(FriendlyFeedbackCategory c,String s,String...args){FriendlyFeedbackMessage m=getMessage(s,args);m.togglePrefix(prefixSample.hasPrefix());m.setSubdivision(prefixSample.getSubdivision());getFeedbackOf(c).add(m);} public FriendlyFeedbackMessage getMessage(String s,String...args){return generateMessage(s,args);} public static void log(FriendlyFeedbackProvider p,FriendlyFeedbackCategory c,String s,String...args){if(p!=null)p.log(c,s,args);} public void activatePrefix(boolean use,String subdivision){prefixSample=new FriendlyFeedbackMessage("",use,subdivision);} public int messagesTotal(FriendlyFeedbackCategory c){return getFeedbackOf(c).size();} public int messagesTotal(){return feedback.values().stream().mapToInt(List::size).sum();}
 public static FriendlyFeedbackMessage generateMessage(String s,String...args){return new FriendlyFeedbackMessage(format(s,args));} public static FriendlyFeedbackMessage generateMessage(FriendlyFeedbackMessage base,String s,String...args){return new FriendlyFeedbackMessage(format(s,args),base.hasPrefix(),base.getSubdivision());} public static String quickForConsole(FriendlyFeedbackPalette p,String s,String...args){return generateMessage(s,args).forConsole(p);} public static String quickForPlayer(FriendlyFeedbackPalette p,String s,String...args){return generateMessage(s,args).forPlayer(p);} private static String format(String s,String...args){if(args==null||args.length==0)return s;try{return MessageFormat.format(s,(Object[])args);}catch(Exception e){String out=s;for(int i=0;i<args.length;i++)out=out.replace("{"+i+"}",args[i]);return out;}}
}
